duckdb work/analysis.duckdb <<'EOF'
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;
CREATE OR REPLACE VIEW facilities AS SELECT * FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet');
