SELECT tier, count(*) n FROM facilities GROUP BY tier ORDER BY n DESC;
SELECT entity_kind, count(*) FROM facilities GROUP BY 1;
SELECT basis, count(*) FROM facilities GROUP BY 1;
SELECT geom_method, count(*) FROM facilities GROUP BY 1;
SELECT source, count(*) FROM facilities GROUP BY 1;
SELECT * FROM facilities LIMIT 5;
EOF

