      CASE tier WHEN 'membership_muni' THEN 1 WHEN 'intake_point' THEN 2 WHEN 'slaughter_point' THEN 2 WHEN 'mill_point' THEN 3 WHEN 'gravity_catchment' THEN 4 END ASC,
      distance_km ASC NULLS LAST,
      evidence_value DESC,
      entity_id ASC
  ) AS rnk
FROM candidates_flagged;

CREATE OR REPLACE TABLE candidates_top5 AS
SELECT * FROM candidates_ranked WHERE rnk <= 5;

SELECT cod_imovel, rnk, entity_id, tier, entity_kind, basis, distance_km, evidence_value, nearest_by_far
FROM candidates_top5 ORDER BY cod_imovel, rnk;
EOF

